CREATE TABLE IF NOT EXISTS report2_provider_budget_v2(provider TEXT NOT NULL,accounting_period TEXT NOT NULL,project_cap INTEGER NOT NULL,scheduled_cap INTEGER NOT NULL,spent_or_outstanding INTEGER NOT NULL DEFAULT 0,scheduled_spent_or_outstanding INTEGER NOT NULL DEFAULT 0,last_reservation_key TEXT,version INTEGER NOT NULL DEFAULT 0,updated_ts INTEGER NOT NULL,PRIMARY KEY(provider,accounting_period));
CREATE TABLE IF NOT EXISTS report2_provider_reservation_v2(provider TEXT NOT NULL,accounting_period TEXT NOT NULL,logical_request_id TEXT NOT NULL,attempt_no INTEGER NOT NULL,reservation_key TEXT NOT NULL UNIQUE,category TEXT NOT NULL,units INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('RESERVED','CONFIRMED','UNKNOWN')),created_ts INTEGER NOT NULL,updated_ts INTEGER NOT NULL,PRIMARY KEY(provider,accounting_period,logical_request_id,attempt_no));
